import Ajv, {type ValidateFunction} from 'ajv/dist/ajv.js';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaValidator = new Ajv({strict: false, validateFormats: false});
  private readonly validators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(definition: ToolDefinition): ValidateFunction {
    const cached = this.validators.get(definition.inputSchema);
    if (cached) return cached;

    try {
      const validator = this.schemaValidator.compile(validationSchema(definition.inputSchema));
      this.validators.set(definition.inputSchema, validator);
      return validator;
    } catch (error) {
      const message = error instanceof Error ? error.message : 'unknown schema error';
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${message}`, {cause: error});
    }
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    if (typeof definition !== 'function') {
      this.validatorFor(resolved);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Returns input-schema rejections; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.validatorFor(definition);
    if (!validator(input)) return {result: formatValidationErrors(validator.errors)};
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

interface ValidationError {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  schemaPath?: string;
  message?: string;
  params: object;
}

function validationSchema(schema: Record<string, unknown>): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(schema).flatMap(([keyword, value]) => {
      if (
        keyword === 'properties' ||
        keyword === 'patternProperties' ||
        keyword === '$defs' ||
        keyword === 'definitions'
      ) {
        if (!isRecord(value)) return [[keyword, value]];
        return [
          [keyword, Object.fromEntries(Object.entries(value).map(([name, nested]) => [name, projectSchema(nested)]))],
        ];
      }
      if (keyword === 'items') return [[keyword, projectSchema(value)]];
      if (['type', 'enum', 'required', '$ref', '$schema'].includes(keyword)) return [[keyword, value]];
      return [];
    })
  );
}

function projectSchema(value: unknown): unknown {
  return isRecord(value) ? validationSchema(value) : value;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function formatValidationErrors(errors: ValidationError[] | null | undefined): string {
  if (!errors?.length) return 'Tool input does not match the declared schema.';

  return errors.map(formatValidationError).join('; ');
}

function formatValidationError(error: ValidationError): string {
  if (error.keyword === 'required') {
    return `${joinInstancePath(requiredPropertyParentPath(error), validationParameter(error, 'missingProperty'))} is required.`;
  }
  if (error.keyword === 'type') {
    return `${errorPath(error)} must be a ${String(validationParameter(error, 'type'))}.`;
  }
  if (error.keyword === 'enum') {
    return `${errorPath(error)} must match an allowed value.`;
  }
  return `${error.instancePath || '/'} ${error.message ?? 'does not match the declared schema'}.`;
}

function errorPath(error: ValidationError): string {
  return normalizeInstancePath(error.instancePath || error.dataPath) || '/';
}

function validationParameter(error: ValidationError, parameter: string): unknown {
  return (error.params as Record<string, unknown>)[parameter];
}

function joinInstancePath(instancePath: string | undefined, property: unknown): string {
  return `${instancePath || ''}/${String(property)}`;
}

function requiredPropertyParentPath(error: ValidationError): string | undefined {
  return normalizeInstancePath(error.instancePath || error.dataPath) || parentPathFromSchemaPath(error.schemaPath);
}

function normalizeInstancePath(path: string | undefined): string | undefined {
  if (!path || path.startsWith('/')) return path;
  return path.replaceAll('.', '/');
}

function parentPathFromSchemaPath(schemaPath: string | undefined): string | undefined {
  if (!schemaPath) return undefined;

  const propertySegments = schemaPath
    .split('/')
    .slice(1, -1)
    .filter(segment => segment !== 'properties');
  return propertySegments.length ? `/${propertySegments.join('/')}` : undefined;
}
